def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    # Build the Aho-Corasick trie.
    children = [{}]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            if char not in children[state]:
                children[state][char] = len(children)
                children.append({})
                terminal.append(False)
            state = children[state][char]
        terminal[state] = True

    # Complete transitions and propagate terminal states along failure links.
    failure = [0] * len(children)
    queue = []
    for char in alphabet:
        if char in children[0]:
            queue.append(children[0][char])
        else:
            children[0][char] = 0

    for state in queue:
        terminal[state] |= terminal[failure[state]]
        for char in alphabet:
            if char in children[state]:
                nxt = children[state][char]
                failure[nxt] = children[failure[state]][char]
                queue.append(nxt)
            else:
                children[state][char] = children[failure[state]][char]

    safe_states = [state for state in range(len(children)) if not terminal[state]]
    index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for state in safe_states:
        row = matrix[index[state]]
        for char in alphabet:
            nxt = children[state][char]
            if not terminal[nxt]:
                row[index[nxt]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] = (result[j] + value * weight) % MOD
            vector = result

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] = (
                                squared[i][j] + value * weight
                            ) % MOD
            matrix = squared

    return sum(vector) % MOD
